<?php $page='posts';require __DIR__.'/_head.php';$msg='';$edit=null;if(isset($_GET['edit'])){$st=db()->prepare('SELECT * FROM posts WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}if(isset($_GET['delete'])){check_csrf();$st=db()->prepare('SELECT image_url FROM posts WHERE id=?');$st->execute([(int)$_GET['delete']]);$old=$st->fetch();db()->prepare('DELETE FROM posts WHERE id=?')->execute([(int)$_GET['delete']]);delete_upload($old['image_url']??null);header('Location:posts.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();$id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$content=trim($_POST['content']??'');if(!$title||!$content)throw new RuntimeException('Title and content are required.');$slug=slugify($_POST['slug']?:$title);$image=upload_image('image','uploads/blog');$status=$_POST['status']==='published'?'published':'draft';$published=$status==='published'?date('Y-m-d H:i:s'):null;if($id){$oldst=db()->prepare('SELECT image_url FROM posts WHERE id=?');$oldst->execute([$id]);$old=$oldst->fetch();$sql='UPDATE posts SET category_id=?,title=?,slug=?,excerpt=?,content=?,meta_title=?,meta_description=?,status=?,published_at=?'.($image?',image_url=?':'').' WHERE id=?';$args=[($_POST['category_id']?:null),$title,$slug,trim($_POST['excerpt']??''),$content,trim($_POST['meta_title']??''),trim($_POST['meta_description']??''),$status,$published];if($image)$args[]=$image;$args[]=$id;db()->prepare($sql)->execute($args);if($image)delete_upload($old['image_url']??null);$msg='Post updated.';}else{db()->prepare('INSERT INTO posts(category_id,title,slug,excerpt,content,image_url,meta_title,meta_description,status,published_at) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([($_POST['category_id']?:null),$title,$slug,trim($_POST['excerpt']??''),$content,$image,trim($_POST['meta_title']??''),trim($_POST['meta_description']??''),$status,$published]);$msg='Post created.';}$edit=null;}catch(Throwable $e){$msg=$e->getMessage();}}$cats=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();$rows=db()->query('SELECT p.*,c.name category_name FROM posts p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();?><div class="topbar"><h1>Blog Posts</h1></div><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><div class="panel"><h2><?=$edit?'Edit post':'Create post'?></h2><form class="form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="row"><label>Title<input name="title" required value="<?=e($edit['title']??'')?>"></label><label>Slug<input name="slug" value="<?=e($edit['slug']??'')?>"></label></div><div class="row"><label>Category<select name="category_id"><option value="">No category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$edit&&$edit['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="draft" <?=(!$edit||$edit['status']==='draft')?'selected':''?>>Draft</option><option value="published" <?=$edit&&$edit['status']==='published'?'selected':''?>>Published</option></select></label></div><label>Excerpt<textarea name="excerpt" style="min-height:90px"><?=e($edit['excerpt']??'')?></textarea></label><label>Content<textarea id="editor" name="content" required><?=e($edit['content']??'')?></textarea></label><div class="row"><label>Featured image<input type="file" name="image" accept="image/*"></label><label>Meta title<input name="meta_title" maxlength="220" value="<?=e($edit['meta_title']??'')?>"></label></div><label>Meta description<textarea name="meta_description" style="min-height:90px"><?=e($edit['meta_description']??'')?></textarea></label><button class="btn primary">Save post</button></form></div><div class="panel" style="margin-top:20px"><h2>All posts</h2><table class="table"><tr><th>Title</th><th>Category</th><th>Status</th><th>Updated</th><th></th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['title'])?></b></td><td><?=e($r['category_name'])?></td><td><?=e($r['status'])?></td><td><?=e($r['updated_at'])?></td><td class="actions"><a class="btn" href="?edit=<?=$r['id']?>">Edit</a><a class="btn danger" onclick="return confirm('Delete post?')" href="?delete=<?=$r['id']?>&csrf=<?=e(csrf())?>">Delete</a></td></tr><?php endforeach;?></table></div><script src="https://cdn.ckeditor.com/4.22.1/standard/ckeditor.js"></script><script>CKEDITOR.replace('editor');</script><?php require __DIR__.'/_foot.php';
